  const conf = orders.filter(o => ["tasdiqlandi", "bajarilmoqda", "yakunlandi"].includes(o.status)).length + books.filter(b => ["tasdiqlandi", "bajarilmoqda", "bajarildi"].includes(b.status)).length;
  const committed = orders.filter(o => o.vendorId && o.status !== "bekor").reduce((a, o) => a + oTotal(o), 0) + books.filter(b => ["tasdiqlandi", "bajarildi"].includes(b.status)).reduce((a, b) => a + rbTotal(b), 0);
  const pending = orders.filter(o => !o.vendorId && o.status !== "bekor").reduce((a, o) => a + oTotal(o), 0) + books.filter(b => b.status === "kutilmoqda").reduce((a, b) => a + rbTotal(b), 0);
