  "t-add": (f, fd) => { const e = EV(f.dataset.e); e.tables = e.tables || []; e.tables.push({ no: (Math.max(0, ...e.tables.map(t => t.no)) + 1), name: String(fd.get("name") || "").trim(), seats: Math.max(2, +fd.get("seats") || 10) }); commitS(); },
