/* ---------- RSVP va ulashish sahifalari (kirishsiz) ---------- */
function miniHead(title) { return `<header class="share-hd"><div class="wrap row between"><div class="brand"><span class="mk">${logo(28)}</span><span>CaterFlow<small>${esc(title)}</small></span></div><div class="lang" role="group">${["uz", "ru", "en"].map(l => `<button type="button" class="${S.lang === l ? "on" : ""}" data-a="lang" data-l="${l}">${l.toUpperCase()}</button>`).join("")}</div></div></header>`; }
function pRSVP(token) {
  const e = (db.events || []).find(x => x.rsvpToken === token), done = S.flash && S.flash.kind === "rsvp" ? S.flash : null; if (done) S.flash = null;
  if (!e) return miniHead("RSVP") + `<section class="section"><div class="wrap">${emptyS(L("Taklifnoma topilmadi", "Приглашение не найдено", "Invitation not found"))}</div></section>`;
  const host = CLs(e.clientId), wed = /to‘y/i.test(e.type);
  return miniHead(L("Taklifnoma", "Приглашение", "Invitation")) + `<section class="hero">${ornament()}<div class="wrap" style="position:relative;padding:48px 20px;text-align:center"><span class="eyebrow">${esc(evL(e.type))}</span><h1 style="margin-top:10px">${esc(e.title)}</h1><p class="lead" style="margin:12px auto 0">${dowL(e.date)}, ${dL(e.date, true)}${e.time ? ` · ${esc(e.time)}` : ""}${e.venue ? ` · ${esc(e.venue)}` : ""}</p></div></section>
  <section class="section-sm"><div class="wrap" style="max-width:560px">${done ? `<div class="card stack-s" style="text-align:center">${icoBox(done.yes ? "rings" : "heart", 30)}<h2>${done.yes ? L("Rahmat! Sizni kutamiz", "Спасибо! Ждём вас", "Thank you! See you there") : L("Javobingiz uchun rahmat", "Спасибо за ответ", "Thanks for letting us know")}</h2><p class="muted">${esc(host ? firstName(host.name) : "")} ${L("javobingizni oldi.", "получил(а) ваш ответ.", "has your reply.")}</p></div>` : `<form class="card stack-s" data-f="rsvp" data-t="${esc(token)}"><h3>${L("Kelasizmi?", "Вы придёте?", "Will you attend?")}</h3><div class="field"><label for="rv-n2">${L("Ism yoki oila", "Имя или семья", "Name or family")}</label><input id="rv-n2" name="name" required></div><div class="f-grid"><div class="field"><label for="rv-c2">${L("Necha kishi", "Сколько человек", "Party size")}</label><input id="rv-c2" name="count" type="number" min="1" max="20" value="2"></div><div class="field"><label for="rv-p2">${L("Telefon (ixtiyoriy)", "Телефон (необязательно)", "Phone (optional)")}</label><input id="rv-p2" name="phone" type="tel"></div></div>${wed ? `<div class="field"><label for="rv-s2">${L("Kim tomondan", "С чьей стороны", "Whose side")}</label><select id="rv-s2" name="side">${[["kelin", L("Kelin tomoni", "Сторона невесты", "Bride’s side")], ["kuyov", L("Kuyov tomoni", "Сторона жениха", "Groom’s side")], ["", L("Do‘stlar", "Друзья", "Friends")]].map(([v, l]) => optS(v, l)).join("")}</select></div>` : ""}<div class="row"><button class="btn btn-gold btn-lg grow" type="submit" name="go" value="yes">${L("Kelaman", "Приду", "I’ll be there")}</button><button class="btn btn-lg" type="submit" name="go" value="no">${L("Kela olmayman", "Не смогу", "Can’t make it")}</button></div></form>`}</div></section>`;
}
SFORM.rsvp = (f, fd) => {
  const e = (db.events || []).find(x => x.rsvpToken === f.dataset.t), name = String(fd.get("name")).trim(), count = Math.max(1, +fd.get("count") || 1), ans = f._ans === "no" ? "no" : "yes";
  (e.guestList = e.guestList || []).unshift({ id: uid("g"), name, phone: String(fd.get("phone") || "").trim(), count, rsvp: ans, side: fd.get("side") || "", table: null, at: Date.now(), via: "rsvp" });
  cnotifyC(e.clientId, ans === "yes" ? [`RSVP: ${name} (${count} kishi) — keladi`, `RSVP: ${name} (${count}) — придёт`, `RSVP: ${name} (${count}) — coming`] : [`RSVP: ${name} — kela olmaydi`, `RSVP: ${name} — не придёт`, `RSVP: ${name} — can’t come`], { view: "c-event", param: e.id });
  S.flash = { kind: "rsvp", yes: ans === "yes" }; commitS(); window.scrollTo(0, 0);
};
document.addEventListener("click", ev => { const b = ev.target.closest("form[data-f=rsvp] button[type=submit]"); if (b) b.form._ans = b.value; }, true);
function pShare(token) {
  const e = (db.events || []).find(x => x.share && x.share.token === token); if (!e) return miniHead("") + `<section class="section"><div class="wrap">${emptyS(L("Sahifa topilmadi", "Страница не найдена", "Page not found"))}</div></section>`;
  const host = CLs(e.clientId), k = evStats(e), sh = e.share, o = k.orders.find(x => x.status !== "bekor"), s = o ? (oQuoteS(o) ? SET(oQuoteS(o).setId) : o.cart ? SET(o.cart.setId) : null) : null, picked = new Set((o && o.cart && o.cart.choices || []).flatMap(x => x[1]));
  const rents = k.books.filter(b => !["rad", "bekor"].includes(b.status));
  return miniHead(host && host.agency ? host.agency : L("Tadbir rejasi", "План события", "Event plan")) + `<section class="hero">${ornament()}<div class="wrap" style="position:relative;padding:44px 20px"><span class="eyebrow">${esc(host && host.agency ? host.agency : "CaterFlow")} · ${L("tadbir rejasi", "план события", "event plan")}</span><h1 style="margin-top:10px">${esc(e.title)}</h1><p class="lead">${dowL(e.date)}, ${dL(e.date, true)}${e.time ? ` · ${esc(e.time)}` : ""} · ${e.guests} ${L("kishi", "гостей", "guests")}${e.venue ? ` · ${esc(e.venue)}` : ""}</p>${sh.status === "approved" ? `<p style="margin-top:12px">${pillS(ic("check", 12) + " " + L("Siz rejani tasdiqlagansiz", "Вы утвердили план", "You approved this plan"), "good")}</p>` : ""}</div></section>
  <section class="section-sm"><div class="wrap layout-side"><div class="stack">${s ? `<section class="card"><div class="card-h"><div><span class="small muted">${esc(VV(s.vendorId).name)}</span><h3>${L("Menyu", "Меню", "Menu")}: ${esc(o.cart && o.cart.built ? L("maxsus set", "особый сет", "custom set") : s.name)}</h3></div>${sh.showBudget ? `<b class="num">${sm(oTotal(o))}</b>` : ""}</div>${menuList(setLines(s), picked)}</section>` : ""}
    ${rents.length ? `<section class="card"><h3>${L("Jihozlar va xizmatlar", "Оборудование и услуги", "Equipment and services")}</h3><ul class="feed" style="margin-top:8px">${rents.map(b => b.items.map(x => `<li><span class="small"><strong>${esc(x.name)}</strong> · ${num(x.qty)} ${unitL(x.unit)} <span class="faint">· ${esc(VV(b.vendorId).name)}</span></span>${sh.showBudget ? `<span class="small num">${sm(x.qty * x.price * (x.days || 1))}</span>` : ""}</li>`).join("")).join("")}</ul></section>` : ""}
    ${(e.timeline || []).length ? `<section class="card"><h3>${L("Dastur", "Программа", "Programme")}</h3><ol class="tl" style="margin-top:8px">${e.timeline.slice().sort((a, b) => a.t.localeCompare(b.t)).map(x => `<li><b>${esc(x.t)}</b><span>${esc(x.text)}</span><span></span></li>`).join("")}</ol></section>` : ""}</div>
    <aside class="card sticky stack-s">${sh.showBudget ? `<div class="sum"><div class="ln"><span>${L("Jami", "Итого", "Total")}</span><b class="num">${sm(k.committed + k.pending)}</b></div></div>` : ""}${sh.status === "approved" ? `<div class="note good">${ic("check", 16)}<span>${L("Tasdiqlangan", "Утверждено", "Approved")} · ${agoL(sh.approvedAt || Date.now())}</span></div>` : `<button type="button" class="btn btn-gold btn-lg btn-block" data-a="sh-approve" data-t="${esc(token)}">${ic("check", 18)} ${L("Rejani tasdiqlayman", "Утверждаю план", "Approve the plan")}</button>`}<form data-f="sh-comment" data-t="${esc(token)}" class="stack-s"><label class="lbl" for="sc-t">${L("Izoh yoki o‘zgartirish istagi", "Комментарий или пожелание", "Comment or change request")}</label><textarea id="sc-t" class="input" name="text" required></textarea><button class="btn" type="submit">${L("Yuborish", "Отправить", "Send")}</button></form>${(sh.comments || []).length ? `<ul class="feed">${sh.comments.slice(-4).map(x => `<li><span class="small">“${esc(x.text)}”</span><span class="tiny faint">${agoL(x.at)}</span></li>`).join("")}</ul>` : ""}<p class="tiny muted">${L(`Rejani ${host ? esc(host.agency || host.name) : "event menejer"} tayyorladi. Savollar uchun unga yozing.`, `План подготовил(а) ${host ? esc(host.agency || host.name) : "ивент-менеджер"}. Вопросы — к нему/ней.`, `Prepared by ${host ? esc(host.agency || host.name) : "your event planner"}. Questions? Ask them.`)}</p></aside></div></section>`;
}
SACT["sh-approve"] = el => { const e = db.events.find(x => x.share && x.share.token === el.dataset.t); e.share.status = "approved"; e.share.approvedAt = Date.now(); cnotifyC(e.clientId, [`Mijozingiz “${e.title}” rejasini tasdiqladi`, `Клиент утвердил план «${e.title}»`, `Your client approved “${e.title}”`], { view: "c-event", param: e.id }); commitS(); toastS(L("Rahmat! Reja tasdiqlandi", "Спасибо! План утверждён", "Thanks! Plan approved")); };
SFORM["sh-comment"] = (f, fd) => { const e = db.events.find(x => x.share && x.share.token === f.dataset.t); (e.share.comments = e.share.comments || []).push({ at: Date.now(), from: "client", text: String(fd.get("text")).trim() }); cnotifyC(e.clientId, [`Mijozingiz izoh qoldirdi: “${fd.get("text")}”`, `Клиент оставил комментарий: «${fd.get("text")}»`, `Your client commented: “${fd.get("text")}”`], { view: "c-event", param: e.id }); commitS(); toastS(L("Yuborildi", "Отправлено", "Sent")); };

const gcalURL = e => { const d = e.date.replace(/-/g, ""), t = (e.time || "18:00").replace(":", "") + "00", end = String(Math.min(23, +(e.time || "18:00").slice(0, 2) + 4)).padStart(2, "0") + (e.time || "18:00").slice(3, 5) + "00"; return "https://calendar.google.com/calendar/render?action=TEMPLATE&text=" + encodeURIComponent(e.title) + "&dates=" + d + "T" + t + "/" + d + "T" + end + "&location=" + encodeURIComponent(e.venue || "") + "&details=" + encodeURIComponent("CaterFlow: " + location.href.split("#")[0] + "#/kabinet/tadbir/" + e.id); };
SACT["rb-cancel"] = el => { const b = RB(el.dataset.id); b.status = "bekor"; b.history.push({ at: Date.now(), text: "Mijoz bekor qildi" }); notifyV(b.vendorId, `${b.id}: mijoz ijara buyurtmasini bekor qildi`, { view: "vsite", param: "rbook" }); logS(`${b.id}: mijoz ijara buyurtmasini bekor qildi`); commitS(); toastS(L("Bekor qilindi", "Отменено", "Cancelled")); };

/* tadbir kabineti: hozir eng kerakli bitta qadam */
function evNext(e, k) {
  const d = daysBetween(today(), e.date), yes = k.rsvp, its = evItems(e), pend = [...k.orders.filter(o => cartPend(o)), ...k.books.filter(b => b.status === "kutilmoqda")], rej = k.books.filter(b => b.status === "rad"), unpaid = k.orders.filter(o => o.vendorId && o.status !== "bekor" && oPaid(o) < oTotal(o) * 0.3), overdue = (e.checklist || []).filter(x => !x.done && x.due && x.due < today());
  let t, p, b = "";
  if (e.status === "yakunlandi") return "";
  if (d === 0 || d === 1) { t = L("Tadbir kuni — jonli kuzatuv", "День события — онлайн", "Event day — follow live"); p = L("Har bir vendor holatini shu yerda ko‘rasiz.", "Статус каждого вендора — здесь.", "See every vendor’s status here."); b = `<button type="button" class="btn btn-gold" data-a="go" data-to="kabinet/tadbir/${e.id}/kun">${ic("activity", 15)} ${L("Jonli kuzatish", "Смотреть", "Follow live")}</button>`; }
  else if (!k.orders.length && !its.leads.length) { t = L("Avval ovqatni tanlang", "Сначала выберите еду", "Start with the food"); p = L("Catering tanlansa, qolgan reja shunga qarab tuziladi.", "Остальной план строится вокруг меню.", "Everything else is planned around the menu."); b = `<button type="button" class="btn btn-gold" data-a="ev-add" data-id="${e.id}" data-to="catering">${L("Catering tanlash", "Выбрать кейтеринг", "Choose catering")}</button>`; }
  else if (rej.length) { t = L(`${VV(rej[0].vendorId).name} rad etdi — boshqasini tanlang`, `${VV(rej[0].vendorId).name} отказал — выберите другого`, `${VV(rej[0].vendorId).name} declined — pick another`); p = esc(rej[0].reason || ""); b = `<button type="button" class="btn btn-gold" data-a="ev-add" data-id="${e.id}" data-to="ijara" data-c2="${rej[0].items[0].cat}">${L("Muqobil topish", "Найти замену", "Find an alternative")}</button>`; }
  else if (pend.length) { t = L(`${pend.length} ta ishtirokchi tasdig‘i kutilmoqda`, `Ждём подтверждения: ${pend.length}`, `${pend.length} provider(s) still to confirm`); p = L("Odatda 2 soat ichida. Tasdiqlansa SMS va bildirishnoma keladi.", "Обычно в течение 2 часов, придёт SMS и уведомление.", "Usually within 2 hours; you’ll get an SMS and a notification."); }
  else if (unpaid.length) { const o = unpaid[0]; t = L(`${VV(o.vendorId).name}: 30% avans — ${sm(Math.round(oTotal(o) * 0.3))}`, `${VV(o.vendorId).name}: аванс 30% — ${sm(Math.round(oTotal(o) * 0.3))}`, `${VV(o.vendorId).name}: 30% advance — ${sm(Math.round(oTotal(o) * 0.3))}`); p = L("Naqd yoki o‘tkazma orqali vendorga. Qayd etilsa shu yerda ko‘rinadi.", "Наличными или переводом вендору. Отметка появится здесь.", "Pay the vendor in cash or by transfer; it shows here once recorded."); b = `<button type="button" class="btn btn-gold" data-a="go" data-to="kabinet/tadbir/${e.id}/pul">${L("To‘lov jadvali", "График оплат", "Payment schedule")}</button>`; }
  else if (!yes && d > 2) { t = L("Mehmonlarga taklifnoma yuboring", "Отправьте приглашения гостям", "Send invitations to your guests"); p = L("Havola orqali “kelaman” deb javob berishadi — mehmon soni o‘zi yangilanadi.", "Гости ответят по ссылке — число гостей обновится само.", "Guests reply via the link and your headcount updates itself."); b = `<button type="button" class="btn btn-gold" data-a="go" data-to="kabinet/tadbir/${e.id}/mehmonlar">${ic("users", 15)} ${L("Taklifnoma havolasi", "Ссылка-приглашение", "Invitation link")}</button>`; }
  else if (overdue.length) { t = L(`Muddati o‘tgan vazifa: ${overdue[0].text}`, `Просрочено: ${overdue[0].text}`, `Overdue: ${overdue[0].text}`); p = ""; b = `<button type="button" class="btn btn-gold" data-a="go" data-to="kabinet/tadbir/${e.id}/reja">${L("Checklistni ochish", "Открыть чек-лист", "Open checklist")}</button>`; }
  else { t = L(`Hammasi joyida — tadbirgacha ${d} kun`, `Всё в порядке — до события ${d} дн`, `All set — ${d} days to go`); p = L("Dastur va checklistni to‘ldirib boring.", "Заполняйте программу и чек-лист.", "Keep your programme and checklist up to date."); b = `<button type="button" class="btn" data-a="go" data-to="kabinet/tadbir/${e.id}/reja">${L("Reja", "План", "Plan")}</button>`; }
  return `<section class="nba"><div class="grow"><span class="eyebrow">${L("Keyingi qadam", "Следующий шаг", "Next step")}</span><h3>${t}</h3>${p ? `<p class="small muted">${p}</p>` : ""}</div>${b}</section>`;
}
